import type { Food } from "../src/food.ts";
import { groupOf, isFoodId } from "./ids.ts";

const HEADER =
  "// Generated by scripts/generate.ts from data/foods. Do not edit; edit data/foods instead.";

// A fixed order, so the same foods always give byte-identical files.
const byCode = (foods: Food[]) =>
  [...foods].sort((a, b) => (a.code < b.code ? -1 : a.code > b.code ? 1 : 0));

/** The foods by main food group, the first letter of the code (BLS documentation 2.4), sorted. */
export function groupByLetter(foods: Food[]): Map<string, Food[]> {
  const groups = new Map<string, Food[]>();
  for (const food of byCode(foods)) {
    const letter = groupOf(food.code);
    groups.set(letter, [...(groups.get(letter) ?? []), food]);
  }
  return groups;
}

/** One module per group: one named export per food, so a bundle holds only the foods it imports. */
export function renderGroup(letter: string, foods: Food[]): string {
  const exports = foods.map((food) => {
    if (!isFoodId(food.code) || groupOf(food.code) !== letter) {
      throw new Error(`${food.code} cannot be exported in group ${letter}`);
    }
    const doc = `${food.name.de} (${food.name.en})`.replaceAll("*/", "*\\/");
    return `/** ${doc} */\nexport const ${food.code}: Food = ${JSON.stringify(food)};\n`;
  });
  return `${HEADER}\nimport type { Food } from "../food.ts";\n\n${exports.join("")}`;
}

/** Re-exports only, never a collection of all groups (SPEC 7). */
export function renderIndex(letters: string[]): string {
  const groups = letters.map((letter) => `export * from "./${letter.toLowerCase()}.ts";\n`);
  return `${HEADER}\n${groups.join("")}`;
}

/** The names of one language by code, without values, for picking a food from a list. */
export function renderNames(language: keyof Food["name"], foods: Food[]): string {
  const names = Object.fromEntries(byCode(foods).map((food) => [food.code, food.name[language]]));
  return `${HEADER}\n\nexport const names: Record<string, string> = ${JSON.stringify(names)};\n`;
}
